```python
import functools
import time

def retry(func):
    """
    A decorator that retries a function up to 3 times if an exception is raised.

    Args:
        func (callable): The function to be decorated.

    Returns:
        callable: The wrapped function with retry logic.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        max_attempts = 3
        last_exception = None

        for attempt in range(1, max_attempts + 1):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                print(f"Attempt {attempt} failed: {e}")

                if attempt < max_attempts:
                    print(f"Retrying... ({attempt}/{max_attempts})")
                    # Small delay to allow for transient issues to resolve
                    time.sleep(0.5)
                else:
                    print("Max attempts reached.")

        # If all attempts fail, raise the last caught exception
        if last_exception:
            raise last_exception

    return wrapper

# --- Demonstration Code ---

if __name__ == "__main__":
    # Case 1: A function that fails twice and then succeeds
    counter = 0

    @retry
    def flaky_function():
        global counter
        counter += 1
        if counter < 3:
            raise ValueError("Temporary failure!")
        return "Success after retries!"

    print("Testing flaky_function...")
    try:
        result = flaky_function()
        print(f"Result: {result}")
    except Exception as e:
        print(f"Caught final exception: {e}")

    print("\n" + "-"*30 + "\n")

    # Case 2: A function that always fails
    @retry
    def permanent_failure():
        raise RuntimeError("Permanent error occurred!")

    print("Testing permanent_failure...")
    try:
        permanent_failure()
    except Exception as e:
        print(f"Caught final exception: {e}")
